CREATE OR REPLACE PROCEDURE public.sp_update_classroom(IN p_id uuid, IN p_tenant_id uuid, IN p_name character varying, IN p_display_name character varying, IN p_short_name character varying, IN p_code character varying, IN p_description text, IN p_classroom_type character varying, IN p_status character varying, IN p_age_group character varying, IN p_min_age_months integer, IN p_max_age_months integer, IN p_capacity integer, IN p_current_enrollment integer, IN p_environment character varying, IN p_photo_url text, IN p_draft_data jsonb, IN p_profile_completion_percentage integer, IN p_is_active boolean, IN p_updated_at timestamp with time zone, IN p_updated_by uuid)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE classrooms     SET name = p_name,         display_name = p_display_name,         short_name = p_short_name,         code = p_code,         description = p_description,         classroom_type = p_classroom_type,         status = p_status,         age_group = p_age_group,         min_age_months = p_min_age_months,         max_age_months = p_max_age_months,         capacity = p_capacity,         current_enrollment = p_current_enrollment,         environment = p_environment,         photo_url = p_photo_url,         draft_data = p_draft_data,         profile_completion_percentage = p_profile_completion_percentage,         is_active = p_is_active,         updated_at = p_updated_at,         updated_by = p_updated_by     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
